oracle_cmd:
cd $TMPDIR/csumgen/c12 && for f in *.py *.txt *.md; do [ -f "$f" ] || continue; sed -n "s/.*b64decode('\(.*\)').*/\1/p" "$f" | base64 -d | tr '|' '\n' | awk -v f="$f" '{i=index($0,"="); print f "\t" substr($0,1,i-1) "\t" substr($0,i+1)}'; done | awk -F'\t' '$2=="language"{L[$1]=$3} $2=="next_language"{N[$1]=$3}
 function dfs(a, p, d,   b) { on[a]=1; if (d>bd) {bd=d; bp=p}; for (b in E) if (E[b]==1 && index(b, a SUBSEP)==1) { split(b, x, SUBSEP); if (!on[x[2]]) dfs(x[2], p ">" x[2], d+1) }; on[a]=0 }
 END{for(f in N) if(N[f]!="none") E[L[f], N[f]]=1; bd=0; for(f in L) dfs(L[f], L[f], 1); print bp}'
